-- Feed component_usage -> tab Component_Usage, base year 2026. Generated by scripts/it-handover.mjs; do not edit.
-- Column 1 is ROW_KEY (unique; drop it from the data file). The other columns are in sheet order.
-- Component_Usage: one row per component x product from the demand forecast. Demand columns come from the DEMAND template, one per demand year.
WITH USAGE AS (
  SELECT
    PART_NUMBER,
    PRODUCT_ID,
    MAX(MPN) AS MPN,
    MAX(MANUFACTURER_NAME) AS MANUFACTURER_NAME,
    MAX(PRODUCT_DISPLAY_NAME) AS PRODUCT_DISPLAY_NAME,
    MAX(PROGRAM_NAME) AS PROGRAM_NAME,
    MAX(CUSTOMER_NAME) AS CUSTOMER_NAME,
    MAX(EMS_NAME) AS EMS_NAME,
    MAX(QTY_PER_UNIT) AS QTY_PER_UNIT
    , SUM(IFF(DEMAND_YEAR = 2025, DEMAND_QUANTITY, 0)) AS DEMAND_2025
, SUM(IFF(DEMAND_YEAR = 2026, DEMAND_QUANTITY, 0)) AS DEMAND_2026
, SUM(IFF(DEMAND_YEAR = 2027, DEMAND_QUANTITY, 0)) AS DEMAND_2027
, SUM(IFF(DEMAND_YEAR = 2028, DEMAND_QUANTITY, 0)) AS DEMAND_2028
, SUM(IFF(DEMAND_YEAR = 2029, DEMAND_QUANTITY, 0)) AS DEMAND_2029
, SUM(IFF(DEMAND_YEAR = 2030, DEMAND_QUANTITY, 0)) AS DEMAND_2030
, SUM(IFF(DEMAND_YEAR = 2031, DEMAND_QUANTITY, 0)) AS DEMAND_2031
, SUM(IFF(DEMAND_YEAR = 2032, DEMAND_QUANTITY, 0)) AS DEMAND_2032
, SUM(IFF(DEMAND_YEAR = 2033, DEMAND_QUANTITY, 0)) AS DEMAND_2033
, SUM(IFF(DEMAND_YEAR = 2034, DEMAND_QUANTITY, 0)) AS DEMAND_2034
, SUM(IFF(DEMAND_YEAR = 2035, DEMAND_QUANTITY, 0)) AS DEMAND_2035
, SUM(IFF(DEMAND_YEAR = 2036, DEMAND_QUANTITY, 0)) AS DEMAND_2036
  FROM MECL_PLATFORM.ANALYTICS.COMPONENT_DEMAND_FORECAST
  WHERE IS_SOURCED_BY_US AND PART_KIND = 'COMPONENT'
  GROUP BY PART_NUMBER, PRODUCT_ID
),
PROJECTS AS (
  SELECT PART_NUMBER, PRODUCT_ID, MAX(PROJECT_NAME) AS PROJECT_NAME
  FROM MECL_PLATFORM.ANALYTICS.COMPONENT_WHERE_USED
  GROUP BY PART_NUMBER, PRODUCT_ID
)
SELECT
  U.PART_NUMBER || '|' || U.PRODUCT_ID AS ROW_KEY,
  U.PART_NUMBER AS ME_EC,
  U.MPN AS MPN,
  U.MANUFACTURER_NAME AS MANUFACTURER,
  U.PRODUCT_DISPLAY_NAME AS PRODUCT,
  U.PRODUCT_ID AS PRODUCT_ID,
  P.PROJECT_NAME AS PROJECT,
  U.PROGRAM_NAME AS PROGRAM,
  U.CUSTOMER_NAME AS CUSTOMER,
  U.EMS_NAME AS EMS,
  U.QTY_PER_UNIT::FLOAT AS QTY_PER_UNIT
  , U.DEMAND_2025 AS DEMAND_2025
, U.DEMAND_2026 AS DEMAND_2026
, U.DEMAND_2027 AS DEMAND_2027
, U.DEMAND_2028 AS DEMAND_2028
, U.DEMAND_2029 AS DEMAND_2029
, U.DEMAND_2030 AS DEMAND_2030
, U.DEMAND_2031 AS DEMAND_2031
, U.DEMAND_2032 AS DEMAND_2032
, U.DEMAND_2033 AS DEMAND_2033
, U.DEMAND_2034 AS DEMAND_2034
, U.DEMAND_2035 AS DEMAND_2035
, U.DEMAND_2036 AS DEMAND_2036
FROM USAGE U
LEFT JOIN PROJECTS P ON P.PART_NUMBER = U.PART_NUMBER AND P.PRODUCT_ID = U.PRODUCT_ID
ORDER BY ROW_KEY;
